#[cfg(test)]
mod shard_281_native_tests {
    use super::*;
    use parking_lot::Mutex;
    use rbx_core::signal::Signal;

    fn test_desc() -> EventDescPayload {
        EventDescPayload {
            name: String::new(),
            permissions: 0,
            attributes: 0,
            items: Vec::new(),
            connections: Mutex::new(Vec::new()),
            single: Signal::new(),
            triple: Signal::new(),
            triple_isi: Signal::new(),
            pair_if: Signal::new(),
        }
    }

    fn test_slot() -> SharedPtr<GenericSlotWrapper> {
        SharedPtr::new(GenericSlotWrapper {
            on_prop: None,
            on_pair: None,
            on_single: None,
            on_triple: None,
            on_triple_isi: None,
            on_chat: None,
            on_prop2: None,
            on_pair_if: None,
            on_player_chat: None,
            on_friend: None,
            on_str_inst: None,
        })
    }

    #[test]
    fn connect_generic_void_0x399c3c_retains_slot() {
        let desc = test_desc();
        let slot = test_slot();
        stub_399c3c(&desc as *const EventDescPayload, &slot);
        let guard = desc.connections.lock();
        assert_eq!(guard.len(), 1);
        assert!(SharedPtr::ptr_eq(&guard[0], &slot));
    }

    #[test]
    fn connect_generic_string_0x39a100_retains_slot() {
        let desc = test_desc();
        let slot = test_slot();
        stub_39a100(&desc as *const EventDescPayload, &slot);
        stub_39a100(&desc as *const EventDescPayload, &slot);
        assert_eq!(desc.connections.lock().len(), 2);
    }

    #[test]
    fn get_arg_float_0x39a7d4_extracts_default_throws() {
        assert_eq!(stub_39a7d4(&[Variant::Int(0), Variant::Int(2)], None), 2.0);
        assert_eq!(stub_39a7d4(&[Variant::Int(0)], Some(3.25)), 3.25);
        assert_eq!(
            stub_39a7d4(&[Variant::Int(0), Variant::Text("x".to_string())], Some(0.5)),
            0.5
        );
    }

    #[test]
    #[should_panic(expected = "Argument 2 missing or nil")]
    fn get_arg_float_0x39a7d4_missing_panics() {
        stub_39a7d4(&[], None);
    }
}
